import java.util.*;

public class Solution {
    public static List<String> unreachable(Map<String, List<String>> graph, List<String> roots) {
        Map<String, Integer> color = new HashMap<>();   // 0 white, 1 grey, 2 black
        for (String k : graph.keySet()) color.put(k, 0);
        Deque<String> queue = new ArrayDeque<>();
        for (String r : roots) { color.put(r, 1); queue.add(r); }
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            for (String nxt : graph.getOrDefault(cur, List.of())) {
                if (color.get(nxt) == 0) { color.put(nxt, 1); queue.add(nxt); }
            }
            color.put(cur, 2);
        }
        List<String> dead = new ArrayList<>();
        for (Map.Entry<String, Integer> e : color.entrySet())
            if (e.getValue() == 0) dead.add(e.getKey());
        Collections.sort(dead);
        return dead;
    }
}
